import{_ as o,C as n,o as e,c as d,a2 as a,b as s,w as l,a as i,E,a3 as g}from"./chunks/framework.RycU2wFZ.js";const b=JSON.parse('{"title":"AgentPay 安全与威胁模型规范 (v0)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/specs/security-model.md","filePath":"zh/specs/security-model.md","lastUpdated":null}'),A={name:"zh/specs/security-model.md"};function c(h,t,y,B,x,f){const r=n("Mermaid");return e(),d("div",null,[t[1]||(t[1]=a('<h1 id="agentpay-安全与威胁模型规范-v0" tabindex="-1">AgentPay 安全与威胁模型规范 (v0) <a class="header-anchor" href="#agentpay-安全与威胁模型规范-v0" aria-label="Permalink to &quot;AgentPay 安全与威胁模型规范 (v0)&quot;">​</a></h1><blockquote><p><strong>规范版本：</strong> 1.1.0（公开威胁模型 v0）<br><strong>状态：</strong> 正式生产规范<br><strong>适用运行时：</strong> Python SDK (<code>agentpay</code>)、Go 网关 (<code>services/gateway</code>)</p></blockquote><hr><h2 id="_1-系统上下文与信任边界" tabindex="-1">1. 系统上下文与信任边界 <a class="header-anchor" href="#_1-系统上下文与信任边界" aria-label="Permalink to &quot;1. 系统上下文与信任边界&quot;">​</a></h2><p>AgentPay 运行在非确定性大语言模型（LLM）与确定性密码学金融网络之间的安全边界上。</p>',5)),(e(),s(g,null,{default:l(()=>[E(r,{id:"mermaid-16",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20subgraph%20UntrustedZone%20%5B%E9%9D%9E%E6%8E%88%E4%BF%A1%E5%8C%BA%E5%9F%9F%20(UNTRUSTED%20ZONE)%5D%0A%20%20%20%20%20%20%20%20LLM%5BLLM%20Agent%20%E6%A0%B8%E5%BF%83%20%2F%20%E6%8F%90%E7%A4%BA%E8%AF%8D%5D%0A%20%20%20%20%20%20%20%20ContextMem%5B%E4%B8%8A%E4%B8%8B%E6%96%87%E8%AE%B0%E5%BF%86%E4%B8%8E%E5%B7%A5%E5%85%B7%E8%BE%93%E5%87%BA%5D%0A%20%20%20%20%20%20%20%20PublicWeb%5B%E5%A4%96%E9%83%A8%E7%BD%91%E9%A1%B5%20%2F%20%E7%AC%AC%E4%B8%89%E6%96%B9%20API%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20BuyerHost%20%5B%E4%B9%B0%E6%96%B9%E5%AE%BF%E4%B8%BB%E6%9C%BA%E4%BF%A1%E4%BB%BB%E8%BE%B9%E7%95%8C%20(BUYER%20HOST%20TRUST%20BOUNDARY)%5D%0A%20%20%20%20%20%20%20%20Interceptor%5BAgentPay%20HTTP%20%E6%8B%A6%E6%88%AA%E5%99%A8%5D%0A%20%20%20%20%20%20%20%20Firewall%5B%E9%87%91%E8%9E%8D%E9%98%B2%E7%81%AB%E5%A2%99%20%2F%20%E7%AD%96%E7%95%A5%E5%BC%95%E6%93%8E%5D%0A%20%20%20%20%20%20%20%20DB%5B(%E6%9C%AC%E5%9C%B0%20SQLite%20%E7%AD%96%E7%95%A5%E8%B4%A6%E6%9C%AC)%5D%0A%20%20%20%20%20%20%20%20Signer%5BLocalSigner%20%E5%AF%86%E9%92%A5%E5%BA%93%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20SellerDomain%20%5B%E5%8D%96%E6%96%B9%20%2F%20%E7%BD%91%E5%85%B3%E5%9F%9F%20(SELLER%20%2F%20GATEWAY%20DOMAIN)%5D%0A%20%20%20%20%20%20%20%20Gateway%5BAgentPay%20%E8%87%AA%E6%89%98%E7%AE%A1%E7%BD%91%E5%85%B3%5D%0A%20%20%20%20%20%20%20%20Upstream%5B%E5%86%85%E9%83%A8%E4%B8%9A%E5%8A%A1%E4%B8%8A%E6%B8%B8%20API%5D%0A%20%20%20%20end%0A%0A%20%20%20%20subgraph%20SettlementLayer%20%5B%E7%BB%93%E7%AE%97%E5%B1%82%20(SETTLEMENT%20LAYER)%5D%0A%20%20%20%20%20%20%20%20Facilitator%5BFacilitator%20%E7%BB%93%E7%AE%97%E6%9C%8D%E5%8A%A1%5D%0A%20%20%20%20%20%20%20%20Chain%5B(EVM%20%E5%8C%BA%E5%9D%97%E9%93%BE%20%2F%20Base%20%2F%20Arbitrum)%5D%0A%20%20%20%20end%0A%0A%20%20%20%20LLM%20--%3E%7C%E6%8F%90%E7%A4%BA%E8%AF%8D%E8%BE%93%E5%87%BA%20%2F%20%E6%9C%AA%E6%A0%A1%E9%AA%8C%E5%8A%A8%E4%BD%9C%7C%20Interceptor%0A%20%20%20%20ContextMem%20-.-%3E%7C%E6%BD%9C%E5%9C%A8%E6%8F%90%E7%A4%BA%E8%AF%8D%E6%B3%A8%E5%85%A5%7C%20Interceptor%0A%20%20%20%20Interceptor%20--%3E%7C1.%20%E6%A3%80%E6%9F%A5%E5%B9%B6%E9%A2%84%E7%95%99%E9%85%8D%E9%A2%9D%7C%20Firewall%0A%20%20%20%20Firewall%20--%3E%7C%E5%8E%9F%E5%AD%90%E4%BA%8B%E5%8A%A1%E4%B8%8E%E9%85%8D%E9%A2%9D%E9%94%81%E5%AE%9A%7C%20DB%0A%20%20%20%20Firewall%20--%3E%7C2.%20%E6%89%B9%E5%87%86%E7%9A%84%E6%8C%91%E6%88%98%E8%BD%BD%E8%8D%B7%7C%20Signer%0A%20%20%20%20Signer%20--%3E%7C3.%20EIP-712%20%2F%20EIP-3009%20%E7%AD%BE%E5%90%8D%7C%20Interceptor%0A%20%20%20%20Interceptor%20--%3E%7C4.%20HTTP%20%2B%20PAYMENT-SIGNATURE%7C%20Gateway%0A%20%20%20%20Gateway%20--%3E%7C5.%20%E6%A0%A1%E9%AA%8C%E7%AD%BE%E5%90%8D%7C%20Facilitator%0A%20%20%20%20Gateway%20--%3E%7C6.%20%E5%8F%8D%E5%90%91%E4%BB%A3%E7%90%86%E5%88%86%E5%8F%91%7C%20Upstream%0A%20%20%20%20Facilitator%20--%3E%7C7.%20%E6%89%B9%E9%87%8F%E5%85%8D%20Gas%20%E7%BB%93%E7%AE%97%7C%20Chain%0A%0A%20%20%20%20style%20UntrustedZone%20fill%3A%23ffebee%2Cstroke%3A%23c62828%2Cstroke-width%3A2px%0A%20%20%20%20style%20BuyerHost%20fill%3A%23e8f5e9%2Cstroke%3A%232e7d32%2Cstroke-width%3A2px%0A%20%20%20%20style%20SellerDomain%20fill%3A%23e3f2fd%2Cstroke%3A%231565c0%2Cstroke-width%3A2px%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<h3 id="信任矩阵" tabindex="-1">信任矩阵 <a class="header-anchor" href="#信任矩阵" aria-label="Permalink to &quot;信任矩阵&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">参与方 / 组件</th><th style="text-align:center;">信任级别</th><th style="text-align:left;">依据与说明</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>LLM Agent 与提示词上下文</strong></td><td style="text-align:center;">❌ <strong>非授信</strong></td><td style="text-align:left;">易受提示词注入（Prompt Injection）、越狱与幻觉影响，绝不能持有或接触明文私钥。</td></tr><tr><td style="text-align:left;"><strong>策略引擎（金融防火墙）</strong></td><td style="text-align:center;">🛡️ <strong>授信</strong></td><td style="text-align:left;">独立于模型 Token 执行的进程内确定性代码。</td></tr><tr><td style="text-align:left;"><strong>本地 SQLite 策略账本</strong></td><td style="text-align:center;">🛡️ <strong>授信</strong></td><td style="text-align:left;">运行在排他文件锁（<code>WAL</code> + <code>BEGIN IMMEDIATE</code>）下的本地文件系统存储。</td></tr><tr><td style="text-align:left;"><strong>LocalSigner / 钱包签名器</strong></td><td style="text-align:center;">🛡️ <strong>授信</strong></td><td style="text-align:left;">内存隔离的签名器；仅对通过策略预检的合法 EIP-712 载荷进行签名。</td></tr><tr><td style="text-align:left;"><strong>自托管网关（Gateway）</strong></td><td style="text-align:center;">⚖️ <strong>半授信</strong></td><td style="text-align:left;">负责执行报价与代理请求；其行为受 Facilitator 验签与哈希校验约束。</td></tr><tr><td style="text-align:left;"><strong>外部 API / 第三方上游</strong></td><td style="text-align:center;">❌ <strong>非授信</strong></td><td style="text-align:left;">可能返回恶意天价 402 报价、伪造响应头或在收款后断开连接。</td></tr><tr><td style="text-align:left;"><strong>Facilitator 结算节点</strong></td><td style="text-align:center;">⚖️ <strong>半授信</strong></td><td style="text-align:left;">负责验证签名并打包上链；由于授权签名已密码学绑定收款方（<code>payee</code>），Facilitator 无法盗取或篡改资金流向。</td></tr></tbody></table><hr><h2 id="_2-防御范围内的威胁与缓解机制-买方域" tabindex="-1">2. 防御范围内的威胁与缓解机制（买方域） <a class="header-anchor" href="#_2-防御范围内的威胁与缓解机制-买方域" aria-label="Permalink to &quot;2. 防御范围内的威胁与缓解机制（买方域）&quot;">​</a></h2><p>v0 安全架构明确针对买方侧的 7 类核心威胁向量提供防护：</p><h3 id="t1-金融提示词注入与自我提权" tabindex="-1">T1：金融提示词注入与自我提权 <a class="header-anchor" href="#t1-金融提示词注入与自我提权" aria-label="Permalink to &quot;T1：金融提示词注入与自我提权&quot;">​</a></h3><ul><li><strong>防御机制：</strong> LLM 上下文没有任何可修改策略文件、SQLite 表或预算配置的编程接口。所有安全检查均在调用私钥前由进程内确定性 Python 代码完成。</li></ul><h3 id="t2-失控-agent-死循环耗尽资金" tabindex="-1">T2：失控 Agent 死循环耗尽资金 <a class="header-anchor" href="#t2-失控-agent-死循环耗尽资金" aria-label="Permalink to &quot;T2：失控 Agent 死循环耗尽资金&quot;">​</a></h3><ul><li><strong>防御机制：</strong> 滚动 RPM 频率熔断器（如最高 15 次/分钟）+ 硬性 24 小时滚动预算池。检测到突发流量时立即跳闸进入 <code>OPEN</code> 熔断状态。</li></ul><h3 id="t3-恶意上游天价敲诈与价格暗涨-p1-7" tabindex="-1">T3：恶意上游天价敲诈与价格暗涨 (P1-7) <a class="header-anchor" href="#t3-恶意上游天价敲诈与价格暗涨-p1-7" aria-label="Permalink to &quot;T3：恶意上游天价敲诈与价格暗涨 (P1-7)&quot;">​</a></h3><ul><li><strong>防御机制：</strong> 硬性 <code>max_per_tx_base_units</code> 整数比较 + 严格的收款方/资产/网络白名单校验；支持配置单资源价格上限以抵御突发涨价。</li></ul><h3 id="t4-跨链与跨合约重放攻击" tabindex="-1">T4：跨链与跨合约重放攻击 <a class="header-anchor" href="#t4-跨链与跨合约重放攻击" aria-label="Permalink to &quot;T4：跨链与跨合约重放攻击&quot;">​</a></h3><ul><li><strong>防御机制：</strong> EIP-712 Domain Separator 在密码学上严格绑定 <code>chainId</code>（如 <code>421614</code> / <code>84532</code>）与 <code>verifyingContract</code>（代币合约地址）。</li></ul><h3 id="t5-签名重放与双花攻击" tabindex="-1">T5：签名重放与双花攻击 <a class="header-anchor" href="#t5-签名重放与双花攻击" aria-label="Permalink to &quot;T5：签名重放与双花攻击&quot;">​</a></h3><ul><li><strong>防御机制：</strong> 使用 <code>secrets.token_bytes(32)</code> 生成 EIP-3009 32 字节密码学安全随机 Nonce；网关强制校验 <code>(network, asset, payer, nonce)</code> 联合唯一性。</li></ul><h3 id="t6-延迟提交与套利扣留" tabindex="-1">T6：延迟提交与套利扣留 <a class="header-anchor" href="#t6-延迟提交与套利扣留" aria-label="Permalink to &quot;T6：延迟提交与套利扣留&quot;">​</a></h3><ul><li><strong>防御机制：</strong> 授权签名强制绑定严格的有效期窗口：$\\text{validBefore} = \\text{validAfter} + 300\\text{s}$。过期授权在链上合约层面数学失效。</li></ul><h3 id="t7-高并发预算竞态条件" tabindex="-1">T7：高并发预算竞态条件 <a class="header-anchor" href="#t7-高并发预算竞态条件" aria-label="Permalink to &quot;T7：高并发预算竞态条件&quot;">​</a></h3><ul><li><strong>防御机制：</strong> 在排他性 SQLite 事务（<code>BEGIN IMMEDIATE</code>）内执行评估与锁定，签名生成前先将配额状态置为 <code>RESERVED</code>。</li></ul><hr><h2 id="_3-网关安全与入站威胁防御-卖方网关域-p0-5" tabindex="-1">3. 网关安全与入站威胁防御（卖方网关域, P0-5） <a class="header-anchor" href="#_3-网关安全与入站威胁防御-卖方网关域-p0-5" aria-label="Permalink to &quot;3. 网关安全与入站威胁防御（卖方网关域, P0-5）&quot;">​</a></h2><p>自托管网关明确防御以下 5 类卖方侧威胁：</p><table tabindex="0"><thead><tr><th style="text-align:left;">威胁类别</th><th style="text-align:left;">威胁描述</th><th style="text-align:left;">核心防御机制</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>G1：抢跑抽干资金 / 撤销授权攻击</strong></td><td style="text-align:left;">在“乐观交付”模式下，买方在链上结算前收到数据，随后立即转空钱包余额或调用 <code>cancelAuthorization</code>。</td><td style="text-align:left;">1. 网关在验签阶段查询节点 RPC 核实买方代币余额。<br>2. 高价值路由支持开启 <code>settle_before_deliver: true</code>（先结算确认后交付）。<br>3. 低价值微支付可接受极小违约风险以换取低延迟。</td></tr><tr><td style="text-align:left;"><strong>G2：幂等缓存劫持</strong></td><td style="text-align:left;">攻击者猜测或嗅探他人的 <code>Idempotency-Key</code>，企图不付款直接获取已缓存的付费响应。</td><td style="text-align:left;">幂等缓存严格绑定 <code>(payer_address, idempotency_key)</code> 或 <code>(tenant_id, idempotency_key)</code>；重放请求必须携带同一付款主体的有效凭证。</td></tr><tr><td style="text-align:left;"><strong>G3：SSRF 与内网暴露</strong></td><td style="text-align:left;">恶意 HTTP 请求企图通过反向代理进行路径遍历或探测内网私有地址。</td><td style="text-align:left;">1. 网关路由严格通过静态配置或受控快照定义上游 URL。<br>2. 剥离逐跳（hop-by-hop）请求头与内部鉴权头。<br>3. 禁用向私有子网的 HTTP 自动重定向（<code>follow_redirects=False</code>）。</td></tr><tr><td style="text-align:left;"><strong>G4：402 挑战与 Facilitator DoS 洪泛</strong></td><td style="text-align:left;">攻击者发送海量未认证请求以耗尽 Facilitator 配额或网关 CPU。</td><td style="text-align:left;">1. 对 402 挑战生成实施入站 IP 速率限制。<br>2. 网关对发往 Facilitator <code>/v1/verify</code> 的调用启用熔断保护。</td></tr><tr><td style="text-align:left;"><strong>G5：本地配置文件篡改</strong></td><td style="text-align:left;">本地篡改路由价格或收款地址配置。</td><td style="text-align:left;">网关 YAML 配置文件以只读权限（<code>chmod 400</code>）加载，或在数据库快照模式下通过 SHA-256 指纹强校验。</td></tr></tbody></table><hr><h2 id="_4-v0-明确非目标-暂不防御范围-p0-4-p1-10" tabindex="-1">4. v0 明确非目标（暂不防御范围, P0-4, P1-10） <a class="header-anchor" href="#_4-v0-明确非目标-暂不防御范围-p0-4-p1-10" aria-label="Permalink to &quot;4. v0 明确非目标（暂不防御范围, P0-4, P1-10）&quot;">​</a></h2><p>以下威胁<strong>明确不在 v0 里程碑的防护范围内</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">威胁类别</th><th style="text-align:center;">v0 状态</th><th style="text-align:left;">说明与 2027 演进计划</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>N1：宿主机 Root 权限失陷</strong></td><td style="text-align:center;">❌ <strong>不防护</strong></td><td style="text-align:left;">若攻击者已获取宿主机 root 权限或可直接读取进程内存，即可从 <code>LocalSigner</code> 提取明文私钥。<br><em>2027 计划：</em> 接入硬件安全模块（HSM）与云端 KMS 签名器。</td></tr><tr><td style="text-align:left;"><strong>N2：预算额度内的经济浪费</strong></td><td style="text-align:center;">❌ <strong>不防护</strong></td><td style="text-align:left;">若 Agent 在允许的预算范围内调用了白名单 API，但上游返回了毫无价值的回答，AgentPay 无法替业务判断语义质量。</td></tr><tr><td style="text-align:left;"><strong>N3：上游数据语义质量 / 幻觉内容</strong></td><td style="text-align:center;">❌ <strong>不防护</strong></td><td style="text-align:left;">若上游 API 返回 HTTP 200 但内容失真，AgentPay 仅验证付费调用已完成交付，不验证内容真实性。</td></tr><tr><td style="text-align:left;"><strong>N4：Facilitator 完全拒绝服务 (DoS)</strong></td><td style="text-align:center;">❌ <strong>不防护</strong></td><td style="text-align:left;">若所有 Facilitator 节点离线，交易将无法上链结算；此时买方资金安全（不会被盗），但支付流程暂停。</td></tr><tr><td style="text-align:left;"><strong>N5：非标准代币合约</strong></td><td style="text-align:center;">❌ <strong>不防护</strong></td><td style="text-align:left;">不支持原生 EIP-3009（<code>transferWithAuthorization</code>）的代币无法免 Gas 结算；v0 严格限定标准 USDC 兼容合约。</td></tr><tr><td style="text-align:left;"><strong>N6：恶意进程内工具 (P0-4)</strong></td><td style="text-align:center;">❌ <strong>不防护</strong></td><td style="text-align:left;">在 v0 嵌入式库模式下，LLM 运行时与 SDK 共享同一 Python 进程；具备任意代码执行（<code>eval</code>）或任意文件读写能力的恶意工具可绕过拦截器。<br><em>2027 计划：</em> 演进为以独立操作系统用户运行的进程外本地 Sidecar 守护进程。</td></tr></tbody></table><hr><h2 id="_5-核心安全不变量与运行铁律" tabindex="-1">5. 核心安全不变量与运行铁律 <a class="header-anchor" href="#_5-核心安全不变量与运行铁律" aria-label="Permalink to &quot;5. 核心安全不变量与运行铁律&quot;">​</a></h2><h3 id="不变量-1-防超支铁律-p0-1-p1-9" tabindex="-1">不变量 1：防超支铁律 (P0-1, P1-9) <a class="header-anchor" href="#不变量-1-防超支铁律-p0-1-p1-9" aria-label="Permalink to &quot;不变量 1：防超支铁律 (P0-1, P1-9)&quot;">​</a></h3><ul><li>一旦支付意图进入 <code>SIGNATURE_SENT</code> 状态，任何网络故障<strong>均不得</strong>自动触发配额释放。配额必须保持 <code>RESERVED</code> 锁定状态，直至满足 <code>now &gt; validBefore + 60s</code> <strong>且</strong>链上查询证实该授权尚未被花费。</li></ul><h3 id="不变量-2-单账本不变量-p0-4" tabindex="-1">不变量 2：单账本不变量 (P0-4) <a class="header-anchor" href="#不变量-2-单账本不变量-p0-4" aria-label="Permalink to &quot;不变量 2：单账本不变量 (P0-4)&quot;">​</a></h3><ul><li><strong>一个私钥严格对应唯一一个本地 SQLite 账本文件。</strong> 严禁使用同一钱包私钥在多个挂载不同 SQLite 文件的 Agent 进程中并发运行，否则会导致预算上限被成倍放大。</li></ul><h3 id="不变量-3-默认拒绝-fail-closed" tabindex="-1">不变量 3：默认拒绝（Fail-Closed） <a class="header-anchor" href="#不变量-3-默认拒绝-fail-closed" aria-label="Permalink to &quot;不变量 3：默认拒绝（Fail-Closed）&quot;">​</a></h3><ul><li>在数据库锁超时、序列化错误或策略引擎内部发生任何未捕获异常时，<strong>交易判定必须默认返回 REJECTED（拒绝）</strong>。</li></ul>',35))])}const p=o(A,[["render",c]]);export{b as __pageData,p as default};
